begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
create temp table ad_fx(k text primary key,id uuid,v jsonb);grant all on ad_fx to authenticated;
insert into ad_fx(k,id)select k,gen_random_uuid()from unnest(array['actor','other','session'])k;
create function pg_temp.ad_id(key text)returns uuid language sql as $$select id from ad_fx where k=$1$$;
insert into auth.users(id,email,raw_user_meta_data)select id,'synthetic-appointment-'||id||'@example.test','{}'from ad_fx where k in('actor','other');
update profiles set is_active=true where id in(pg_temp.ad_id('actor'),pg_temp.ad_id('other'));
insert into user_roles(user_id,role)values(pg_temp.ad_id('actor'),'TECH'),(pg_temp.ad_id('other'),'DVM')on conflict do nothing;
insert into auth.sessions(id,user_id,created_at,updated_at)values(pg_temp.ad_id('session'),pg_temp.ad_id('actor'),now(),now());
select ok(relrowsecurity and not has_table_privilege('authenticated',oid,'SELECT')and not has_table_privilege('authenticated',oid,'INSERT')and not has_table_privilege('service_role',oid,'SELECT'),'Appointment links are private')from pg_class where oid='public.appointment_clinical_links'::regclass;
select ok(has_function_privilege('authenticated',oid,'EXECUTE')and not has_function_privilege('anon',oid,'EXECUTE')and not has_function_privilege('service_role',oid,'EXECUTE'),proname||' staff-only')from pg_proc where pronamespace='public'::regnamespace and proname in('read_appointment_dictation','prepare_appointment_dictation');
select set_config('request.jwt.claims',jsonb_build_object('role','authenticated','sub',pg_temp.ad_id('actor'),'session_id',pg_temp.ad_id('session'))::text,true);
set local role authenticated;
insert into ad_fx(k,id)select 'client',id from save_client(auth.uid(),null,null,'Synthetic','Appointment','+13035555582','synthetic-appointment@example.test','EMAIL',null,null);
insert into ad_fx(k,id)select 'pet',id from save_patient(null,pg_temp.ad_id('client'),null,'Synthetic Appointment','Dog','Mixed',null,'unknown','','unknown','unknown','',null,null);
insert into ad_fx(k,id)select 'other_pet',id from save_patient(null,pg_temp.ad_id('client'),null,'Synthetic Other','Cat','Mixed',null,'unknown','','unknown','unknown','',null,null);
insert into ad_fx(k,id,v)select 'appointment',a.id,to_jsonb(a)from save_appointment(auth.uid(),null,null,pg_temp.ad_id('client'),pg_temp.ad_id('pet'),now()+interval '1 day',30,'Synthetic dictation','CONFIRMED',pg_temp.ad_id('other'),'clinic','Synthetic',0,0,null,'Synthetic','{}'::integer[])a;
select is(read_appointment_dictation(auth.uid(),pg_temp.ad_id('pet'),pg_temp.ad_id('appointment'))->>'encounter_id',null::text,'Read creates no encounter');
select throws_ok($$select read_appointment_dictation(auth.uid(),pg_temp.ad_id('other_pet'),pg_temp.ad_id('appointment'))$$,'23514',null,'Wrong patient rejected');
select throws_ok($$select read_appointment_dictation(pg_temp.ad_id('other'),pg_temp.ad_id('pet'),pg_temp.ad_id('appointment'))$$,'42501',null,'Wrong actor rejected');
select throws_ok($$select prepare_appointment_dictation(auth.uid(),pg_temp.ad_id('pet'),pg_temp.ad_id('appointment'),2,null)$$,'PT409',null,'Stale appointment rejected');
insert into ad_fx(k,id,v)select 'encounter',e.id,to_jsonb(e)from prepare_appointment_dictation(auth.uid(),pg_temp.ad_id('pet'),pg_temp.ad_id('appointment'),1,null)e;
select is((select v->>'status'from ad_fx where k='encounter'),'draft','Explicit confirmation creates unsigned draft');
select is((select v->>'created_by'from ad_fx where k='encounter'),auth.uid()::text,'Tech starter attributed independently of assigned doctor');
select ok((select (v->>'visit_at')::timestamptz<=now()from ad_fx where k='encounter'),'Actual visit time used for future scheduled visit');
select is((select v->>'location'from ad_fx where k='encounter'),'2619 Spruce Street, Boulder, CO','Clinic location copied from canonical appointment');
select is((prepare_appointment_dictation(auth.uid(),pg_temp.ad_id('pet'),pg_temp.ad_id('appointment'),1,null)).id,pg_temp.ad_id('encounter'),'Repeated or lost response reopens same encounter');
set local timezone='America/Denver';
select is(read_appointment_dictation(auth.uid(),pg_temp.ad_id('pet'),pg_temp.ad_id('appointment'))->>'context_changed','false','Timezone formatting cannot change appointment identity');
select is((prepare_appointment_dictation(auth.uid(),pg_temp.ad_id('pet'),pg_temp.ad_id('appointment'),1,null)).id,pg_temp.ad_id('encounter'),'Same appointment recovers across database timezones');
set local timezone='UTC';
select is((prepare_appointment_dictation(auth.uid(),pg_temp.ad_id('pet'),pg_temp.ad_id('appointment'),1,pg_temp.ad_id('encounter'))).version,1,'Reopening leaves saved clinical version untouched');
select throws_ok($$select prepare_appointment_dictation(auth.uid(),pg_temp.ad_id('pet'),pg_temp.ad_id('appointment'),1,gen_random_uuid())$$,'23514',null,'Linked encounter cannot be replaced');
reset role;
select is((select count(*)::integer from appointment_clinical_links),1,'Exactly one durable link');
select throws_ok($$update appointment_clinical_links set actor_id=pg_temp.ad_id('other')$$,'23514',null,'Link is immutable');
update appointments set scheduled_at=scheduled_at+interval '1 hour'where id=pg_temp.ad_id('appointment');
set local role authenticated;
select is(read_appointment_dictation(auth.uid(),pg_temp.ad_id('pet'),pg_temp.ad_id('appointment'))->>'context_changed','true','Reschedule detected without rewriting encounter');
select throws_ok($$select prepare_appointment_dictation(auth.uid(),pg_temp.ad_id('pet'),pg_temp.ad_id('appointment'),2,null)$$,'23514',null,'Rescheduled link requires manual review');
reset role;
update appointments set scheduled_at=(select (v->>'scheduled_at')::timestamptz from ad_fx where k='appointment'),status='CANCELLED'where id=pg_temp.ad_id('appointment');
set local role authenticated;
select throws_ok($$select prepare_appointment_dictation(auth.uid(),pg_temp.ad_id('pet'),pg_temp.ad_id('appointment'),3,null)$$,'23514',null,'Cancelled linked appointment blocked');
reset role;
update appointments set status='NO_SHOW'where id=pg_temp.ad_id('appointment');
set local role authenticated;
select throws_ok($$select prepare_appointment_dictation(auth.uid(),pg_temp.ad_id('pet'),pg_temp.ad_id('appointment'),4,null)$$,'23514',null,'No-show linked appointment blocked');
reset role;
update appointments set status='COMPLETED'where id=pg_temp.ad_id('appointment');
set local role authenticated;
select is((prepare_appointment_dictation(auth.uid(),pg_temp.ad_id('pet'),pg_temp.ad_id('appointment'),5,null)).id,pg_temp.ad_id('encounter'),'Completed visit can reopen original draft');
select save_clinical_encounter(pg_temp.ad_id('encounter'),pg_temp.ad_id('pet'),1,now(),'clinic','2619 Spruce Street, Boulder, CO','Original history','Original exam','Original assessment','Original plan');
select sign_clinical_encounter(pg_temp.ad_id('encounter'),2);
select is((prepare_appointment_dictation(auth.uid(),pg_temp.ad_id('pet'),pg_temp.ad_id('appointment'),5,null)).status,'signed','Signed encounter returned read-only without replacement');
select is(read_appointment_dictation(auth.uid(),pg_temp.ad_id('pet'),pg_temp.ad_id('appointment'))->>'encounter_status','signed','Context reports signed status');
reset role;
update pets set archived_at=now()where id=pg_temp.ad_id('pet');
set local role authenticated;
select throws_ok($$select prepare_appointment_dictation(auth.uid(),pg_temp.ad_id('pet'),pg_temp.ad_id('appointment'),5,null)$$,'23514',null,'Inactive patient blocked');
reset role;
update pets set archived_at=null where id=pg_temp.ad_id('pet');
select set_config('request.jwt.claims','{}',true);
update profiles set is_active=false where id=pg_temp.ad_id('actor');
select set_config('request.jwt.claims',jsonb_build_object('role','authenticated','sub',pg_temp.ad_id('actor'),'session_id',pg_temp.ad_id('session'))::text,true);
set local role authenticated;
select throws_ok($$select read_appointment_dictation(auth.uid(),pg_temp.ad_id('pet'),pg_temp.ad_id('appointment'))$$,'42501',null,'Offboarded staff rejected');
reset role;
select set_config('request.jwt.claims','{}',true);
update profiles set is_active=true where id=pg_temp.ad_id('actor');
select set_config('request.jwt.claims',jsonb_build_object('role','authenticated','sub',pg_temp.ad_id('actor'),'session_id',pg_temp.ad_id('session'))::text,true);
delete from auth.sessions where id=pg_temp.ad_id('session');
set local role authenticated;
select throws_ok($$select prepare_appointment_dictation(auth.uid(),pg_temp.ad_id('pet'),pg_temp.ad_id('appointment'),5,null)$$,'42501',null,'Retired session rejected');
reset role;
select is((select status from clinical_audio_policies where version=1),'draft','Processing policy unchanged');
select is((select count(*)::integer from clinical_audio_jobs),0,'No audio uploaded or provider source reserved');
select * from finish();rollback;
